I _think_ this is a new issue with version 2.0.0.  The function generated by has_cache attempts to read the actual cache result into memory before returning that the call is indeed cached.  This is problematic for large cached dataframes, etc.

```
> has_cache(getter)
function (date, arg1) 
{
    mc <- match.call()
    encl <- parent.env(environment())
    called_args <- as.list(mc)[-1]
    default_args <- encl$`_default_args`
    default_args <- default_args[setdiff(names(default_args), 
        names(called_args))]
    called_args[encl$`_omit_args`] <- NULL
    args <- c(lapply(called_args, eval, parent.frame()), lapply(default_args, 
        eval, envir = environment()))
    key <- encl$`_hash`(c(encl$`_f_hash`, args, lapply(encl$`_additional`, 
        function(x) eval(x[[2L]], environment(x)))))

    res <- encl$`_cache`$get(key)  # <---- This should probably be removed?
    return(encl$`_cache`$exists(key))

    if (res$visible) {
        res$value
    }
    else {
        invisible(res$value)
    }
}
```

How can we make this compatible with both versions of memoise?

## 1e47c363786d560b41316bf749480433d42ca304, current

``` r
library(rlang)

cache_attach <- function(algo = "sha512", base_attach = attach, name = paste0(utils::packageName(), "_cache")) {
  force(algo)

  if (!is_attached(name)) {
    env <- new_environment(list(...cache = new_environment()))
    base_attach(env, pos = length(search()) - 1, name = name)
  }
  cache <- search_env(name)$...cache

  cache_reset <- function() {
    rm(list = ls(cache), envir = cache)
  }

  cache_set <- function(key, value) {
    assign(key, value, envir = cache)
  }

  cache_get <- function(key) {
    get(key, envir = cache, inherits = FALSE)
  }

  cache_has_key <- function(key) {
    exists(key, envir = cache, inherits = FALSE)
  }

  list(
    digest = function(...) digest::digest(..., algo = algo),
    reset = cache_reset,
    set = cache_set,
    get = cache_get,
    has_key = cache_has_key,
    keys = function() ls(cache)
  )
}

cachee <- function() "foo"
cachee()
#> [1] "foo"

cachee <<- memoise::memoise(cachee, cache = cache_attach(name = "test"))
cachee()
#> Error in get(key, envir = cache, inherits = FALSE): object 'b41b0123bcd8e4b82ee65ffcbcdb06a8' not found
```

